//! Replays `tests/fixtures/scr_tex_fixtures.txt` through the Rust `UScriptedTexture`
//! kernels. The fixture is generated by `Build/scr_tex_fixture_harness/gen_scr_tex.sh`
//! from the original C++ `DrawString`, `GetCharSize`, `DrawTile`, `PostLoad` and `Tick`.
//! Every record carries the C++ result; each one is checked against the Rust port.

use std::cell::Cell;
use std::collections::HashMap;
use std::ffi::c_void;

use hp2_abi::FColor;
use hp2_engine::canvas_text::Hp2FontChar;
use hp2_engine::scr_tex::{
    ObjPtr, PaletteCache, ScrTexHost, TileRect, char_size, draw_string, draw_tile, post_load, tick,
};
use hp2_engine::tex::{NUM_PAL_COLORS, best_match, color_from_int4};

const FIXTURE: &str = include_str!("fixtures/scr_tex_fixtures.txt");

/// Mip storage. `Cell` makes writes through `ObjPtr` sound while the trait takes `&self`.
type Bytes = Box<[Cell<u8>]>;

fn bytes(src: &[u8]) -> Bytes {
    src.iter().map(|&b| Cell::new(b)).collect()
}

fn zeros(n: usize) -> Bytes {
    (0..n).map(|_| Cell::new(0)).collect()
}

fn read(b: &Bytes) -> Vec<u8> {
    b.iter().map(Cell::get).collect()
}

fn mip_ptr(b: &Bytes) -> ObjPtr {
    ObjPtr(b.as_ptr().cast_mut().cast::<c_void>())
}

fn null() -> ObjPtr {
    ObjPtr(std::ptr::null_mut())
}

/// Object handles are `index + 1`, so the null pointer stays distinct from index 0.
fn handle(i: usize) -> ObjPtr {
    ObjPtr((i + 1) as *mut c_void)
}

fn idx(p: ObjPtr) -> usize {
    p.0 as usize - 1
}

fn opt(p: ObjPtr) -> Option<usize> {
    if p.is_null() { None } else { Some(idx(p)) }
}

struct Tex {
    ubits: i32,
    vbits: i32,
    palette: usize,
    data: Bytes,
}

struct Page {
    tex: Option<usize>,
    chars: Vec<Hp2FontChar>,
}

struct Font {
    cpp: i32,
    remapped: bool,
    remap: HashMap<u16, u16>,
    pages: Vec<Page>,
}

/// In-memory stand-in for the C++ objects. `self_*` fields are the scripted texture.
struct Fake {
    pals: Vec<Vec<FColor>>,
    texs: Vec<Tex>,
    fonts: Vec<Font>,
    texts: Vec<Vec<i32>>,
    ubits: i32,
    vbits: i32,
    palette: usize,
    data: Bytes,
    local: Option<Bytes>,
    source: Option<usize>,
    old_source: Option<usize>,
    /// Texture currently locked as `FTextureInfo`.
    info: Option<usize>,
    cache: PaletteCache,
    logs: Vec<u32>,
}

impl Fake {
    fn new() -> Self {
        Self {
            pals: Vec::new(),
            texs: Vec::new(),
            fonts: Vec::new(),
            texts: Vec::new(),
            ubits: 0,
            vbits: 0,
            palette: 0,
            data: zeros(0),
            local: None,
            source: None,
            old_source: None,
            info: None,
            cache: PaletteCache::new(),
            logs: Vec::new(),
        }
    }

    /// Starts a fresh scripted texture, matching the harness `make_scr`.
    fn start_self(&mut self, ubits: i32, vbits: i32, palette: usize, init: &[u8]) {
        self.ubits = ubits;
        self.vbits = vbits;
        self.palette = palette;
        self.data = bytes(init);
        self.local = None;
        self.source = None;
        self.old_source = None;
        self.info = None;
        self.cache.clear();
    }

    fn dest(&self) -> Vec<u8> {
        read(&self.data)
    }
}

impl ScrTexHost for Fake {
    fn font_chars_per_page(&self, font: ObjPtr) -> i32 {
        self.fonts[idx(font)].cpp
    }

    fn font_remap_char(&self, font: ObjPtr, ch: i32) -> i32 {
        let f = &self.fonts[idx(font)];
        let c = ch as u16;
        let r = if f.remapped {
            f.remap.get(&c).copied().unwrap_or(32)
        } else {
            c
        };
        r as i32
    }

    fn font_page_count(&self, font: ObjPtr) -> i32 {
        self.fonts[idx(font)].pages.len() as i32
    }

    fn font_page_texture(&self, font: ObjPtr, page: i32) -> ObjPtr {
        match self.fonts[idx(font)].pages[page as usize].tex {
            Some(t) => handle(t),
            None => null(),
        }
    }

    fn font_page_char_count(&self, font: ObjPtr, page: i32) -> i32 {
        self.fonts[idx(font)].pages[page as usize].chars.len() as i32
    }

    fn font_page_char(&self, font: ObjPtr, page: i32, index: i32) -> Hp2FontChar {
        self.fonts[idx(font)].pages[page as usize].chars[index as usize]
    }

    fn text_char(&self, text: ObjPtr, index: i32) -> i32 {
        self.texts[idx(text)]
            .get(index as usize)
            .copied()
            .unwrap_or(0)
    }

    fn tex_usize(&self, tex: ObjPtr) -> i32 {
        1 << self.texs[idx(tex)].ubits
    }

    fn tex_vsize(&self, tex: ObjPtr) -> i32 {
        1 << self.texs[idx(tex)].vbits
    }

    fn tex_ubits(&self, tex: ObjPtr) -> i32 {
        self.texs[idx(tex)].ubits
    }

    fn tex_vbits(&self, tex: ObjPtr) -> i32 {
        self.texs[idx(tex)].vbits
    }

    fn tex_mip0(&self, tex: ObjPtr) -> ObjPtr {
        mip_ptr(&self.texs[idx(tex)].data)
    }

    fn tex_palette_colors(&self, tex: ObjPtr, out: &mut [FColor; NUM_PAL_COLORS]) {
        out.copy_from_slice(&self.pals[self.texs[idx(tex)].palette]);
    }

    fn tex_get_local(&self, tex: ObjPtr) -> ObjPtr {
        tex
    }

    fn tex_lock_local(&mut self, tex: ObjPtr) {
        self.info = Some(idx(tex));
    }

    fn tex_lock_now(&mut self, tex: ObjPtr) {
        self.info = Some(idx(tex));
    }

    fn tex_unlock(&mut self, _tex: ObjPtr) {
        self.info = None;
    }

    fn info_mip0(&self) -> ObjPtr {
        match self.info {
            Some(t) => mip_ptr(&self.texs[t].data),
            None => null(),
        }
    }

    fn self_usize(&self) -> i32 {
        1 << self.ubits
    }

    fn self_vsize(&self) -> i32 {
        1 << self.vbits
    }

    fn self_ubits(&self) -> i32 {
        self.ubits
    }

    fn self_vbits(&self) -> i32 {
        self.vbits
    }

    fn self_mip0(&self) -> ObjPtr {
        mip_ptr(&self.data)
    }

    fn self_local_bitmap(&self) -> ObjPtr {
        self.local.as_ref().map_or(null(), mip_ptr)
    }

    fn self_alloc_local_bitmap(&mut self, bytes: i32) -> ObjPtr {
        self.local = Some(zeros(bytes as usize));
        mip_ptr(self.local.as_ref().expect("local was just allocated"))
    }

    fn self_source_texture(&self) -> ObjPtr {
        self.source.map_or(null(), handle)
    }

    fn self_old_source(&self) -> ObjPtr {
        self.old_source.map_or(null(), handle)
    }

    fn self_set_old_source(&mut self, tex: ObjPtr) {
        self.old_source = opt(tex);
    }

    fn self_copy_palette_from(&mut self, tex: ObjPtr) {
        self.palette = self.texs[idx(tex)].palette;
    }

    fn self_palette_colors(&self, out: &mut [FColor; NUM_PAL_COLORS]) {
        out.copy_from_slice(&self.pals[self.palette]);
    }

    fn self_palette_best_match(&self, color: u32) -> u8 {
        best_match(&self.pals[self.palette], color_from_int4(color), 0)
    }

    fn palette_map_lookup(&self, map: ObjPtr, _index: u8) -> u8 {
        assert!(
            map.0.is_null(),
            "palette_map_lookup called with a non-null map"
        );
        panic!("palette_map_lookup: NULL PalMap dereference (use_color && !masked)")
    }

    fn self_notify_render(&mut self) {}

    fn palette_cache(&mut self) -> &mut PaletteCache {
        &mut self.cache
    }

    fn log(&mut self, code: u32) {
        self.logs.push(code);
    }
}

fn tok<'a, I: Iterator<Item = &'a str>>(it: &mut I) -> &'a str {
    it.next().expect("fixture: missing token")
}

fn int<'a, I: Iterator<Item = &'a str>>(it: &mut I) -> i64 {
    tok(it).parse().expect("fixture: bad integer")
}

fn bits<'a, I: Iterator<Item = &'a str>>(it: &mut I) -> u32 {
    u32::from_str_radix(tok(it), 16).expect("fixture: bad hex word")
}

fn hex(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("fixture: bad hex byte"))
        .collect()
}

#[test]
fn scr_tex_fixtures_replay() {
    let mut fake = Fake::new();
    let mut counts: HashMap<&str, usize> = HashMap::new();

    for line in FIXTURE.lines() {
        let mut it = line.split_whitespace();
        let kind = tok(&mut it);
        *counts.entry(kind).or_insert(0) += 1;
        match kind {
            "pal" => {
                let id = int(&mut it) as usize;
                assert_eq!(id, fake.pals.len(), "pal record order: {line}");
                let colors: Vec<FColor> = (0..NUM_PAL_COLORS)
                    .map(|_| color_from_int4(bits(&mut it)))
                    .collect();
                fake.pals.push(colors);
            }
            "tex" => {
                let id = int(&mut it) as usize;
                assert_eq!(id, fake.texs.len(), "tex record order: {line}");
                let ubits = int(&mut it) as i32;
                let vbits = int(&mut it) as i32;
                let palette = int(&mut it) as usize;
                let data = hex(tok(&mut it));
                assert_eq!(data.len(), 1 << (ubits + vbits), "tex size: {line}");
                fake.texs.push(Tex {
                    ubits,
                    vbits,
                    palette,
                    data: bytes(&data),
                });
            }
            "font" => {
                let fi = int(&mut it) as usize;
                assert_eq!(fi, fake.fonts.len(), "font record order: {line}");
                let cpp = int(&mut it) as i32;
                let remapped = int(&mut it) != 0;
                fake.fonts.push(Font {
                    cpp,
                    remapped,
                    remap: HashMap::new(),
                    pages: Vec::new(),
                });
            }
            "remap" => {
                let fi = int(&mut it) as usize;
                let from = int(&mut it) as u16;
                let to = int(&mut it) as u16;
                fake.fonts[fi].remap.insert(from, to);
            }
            "page" => {
                let fi = int(&mut it) as usize;
                let p = int(&mut it) as usize;
                let tid = int(&mut it);
                let nchars = int(&mut it) as usize;
                assert_eq!(p, fake.fonts[fi].pages.len(), "page record order: {line}");
                let chars: Vec<Hp2FontChar> = (0..nchars)
                    .map(|_| Hp2FontChar {
                        start_u: int(&mut it) as i32,
                        start_v: int(&mut it) as i32,
                        u_size: int(&mut it) as i32,
                        v_size: int(&mut it) as i32,
                    })
                    .collect();
                fake.fonts[fi].pages.push(Page {
                    tex: if tid < 0 { None } else { Some(tid as usize) },
                    chars,
                });
            }
            "chr" => {
                let fi = int(&mut it) as usize;
                let ch = int(&mut it) as i32;
                let w = int(&mut it) as i32;
                let h = int(&mut it) as i32;
                let got = char_size(&fake, handle(fi), ch);
                assert_eq!(got, (w, h), "chr record: {line}");
            }
            "case" => {
                let _ci = int(&mut it);
                let ub = int(&mut it) as i32;
                let vb = int(&mut it) as i32;
                let palette = int(&mut it) as usize;
                let init = hex(tok(&mut it));
                assert_eq!(init.len(), 1 << (ub + vb), "case size: {line}");
                fake.start_self(ub, vb, palette, &init);
            }
            "tile" => {
                let _ci = int(&mut it);
                let rect = TileRect {
                    x: f32::from_bits(bits(&mut it)),
                    y: f32::from_bits(bits(&mut it)),
                    xl: f32::from_bits(bits(&mut it)),
                    yl: f32::from_bits(bits(&mut it)),
                    u: f32::from_bits(bits(&mut it)),
                    v: f32::from_bits(bits(&mut it)),
                    ul: f32::from_bits(bits(&mut it)),
                    vl: f32::from_bits(bits(&mut it)),
                };
                let tid = int(&mut it) as usize;
                let masked = int(&mut it) != 0;
                let use_color = int(&mut it) != 0;
                let color = int(&mut it) as u8;
                let expect = hex(tok(&mut it));
                let tex = handle(tid);
                // Mirrors the harness: the source is locked for the draw, then unlocked.
                fake.tex_lock_now(tex);
                draw_tile(&mut fake, rect, tex, masked, use_color, color);
                fake.tex_unlock(tex);
                assert_eq!(fake.dest(), expect, "tile record: {line}");
            }
            "str" => {
                let _ci = int(&mut it);
                let x = int(&mut it) as i32;
                let y = int(&mut it) as i32;
                let fi = int(&mut it) as usize;
                let use_color = int(&mut it) != 0;
                let entry = int(&mut it) as u8;
                let len = int(&mut it) as usize;
                let chars: Vec<i32> = (0..len).map(|_| int(&mut it) as i32).collect();
                let lx = int(&mut it) as i32;
                let expect = hex(tok(&mut it));
                let text = handle(fake.texts.len());
                fake.texts.push(chars);
                let entry = if use_color { Some(entry) } else { None };
                let got = draw_string(&mut fake, handle(fi), x, y, text, entry);
                assert_eq!(got, lx, "str record return value: {line}");
                assert_eq!(fake.dest(), expect, "str record: {line}");
            }
            "pl" => {
                let _ci = int(&mut it);
                let src = int(&mut it);
                let local = tok(&mut it);
                let palette = int(&mut it) as usize;
                fake.source = if src < 0 { None } else { Some(src as usize) };
                post_load(&mut fake);
                match local {
                    "-" => assert!(fake.local.is_none(), "pl record local: {line}"),
                    hex_local => assert_eq!(
                        fake.local.as_ref().map(read),
                        Some(hex(hex_local)),
                        "pl record local: {line}"
                    ),
                }
                assert_eq!(fake.palette, palette, "pl record palette: {line}");
            }
            "tk" => {
                let _ci = int(&mut it);
                let _delta = bits(&mut it);
                let expect = hex(tok(&mut it));
                tick(&mut fake);
                assert_eq!(fake.dest(), expect, "tk record: {line}");
            }
            other => panic!("unknown fixture record kind {other:?}: {line}"),
        }
    }

    for kind in [
        "pal", "tex", "font", "remap", "page", "chr", "case", "tile", "str", "pl", "tk",
    ] {
        assert!(
            counts.get(kind).copied().unwrap_or(0) > 0,
            "fixture has no {kind} records"
        );
    }
    assert!(
        fake.logs.is_empty(),
        "unexpected log codes: {:?}",
        fake.logs
    );
}

/// `DrawTile(bUseColor=1, bMasked=0)` with a visible source pixel dereferences the
/// NULL PalMap in C++, so Rust must reach that deref through the service and fail
/// loudly rather than draw nothing.
#[test]
#[should_panic(expected = "NULL PalMap dereference")]
fn draw_tile_color_unmasked_faults_on_null_palette_map() {
    let mut fake = Fake::new();
    fake.pals.push(vec![color_from_int4(0); NUM_PAL_COLORS]);
    fake.texs.push(Tex {
        ubits: 2,
        vbits: 2,
        palette: 0,
        data: bytes(&[1; 16]),
    });
    fake.start_self(2, 2, 0, &[0; 16]);
    let rect = TileRect {
        x: 0.0,
        y: 0.0,
        xl: 2.0,
        yl: 2.0,
        u: 0.0,
        v: 0.0,
        ul: 2.0,
        vl: 2.0,
    };
    let tex = handle(0);
    fake.tex_lock_now(tex);
    draw_tile(&mut fake, rect, tex, false, true, 0);
}
